<?php
/**
 * Componente: mapa de cobertura interativo (SVG dinâmico) de Alagoas.
 *
 * Uso: require __DIR__ . '/includes/mapa-cobertura.php'; a partir de qualquer
 * página (ex.: cobertura.php), no lugar da antiga <img src="assets/alagoas-full.svg">.
 *
 * O SVG completo do estado (todos os municípios, geometria fixa) fica embutido
 * no JS abaixo — é dado geográfico estático, não conteúdo editorial. As únicas
 * coisas que alguém precisa editar ao expandir a cobertura da MUT são os três
 * arrays PHP logo abaixo: $mutCidadesAtendidas, $mutPinPosicoes e o texto da
 * mensagem de WhatsApp (via mut_whatsapp_link(), já centralizado em data.php).
 */

declare(strict_types=1);

$destacaVizinha = @$_GET["mini-map"] && @$_GET["mini-map"] == 1;

/**
 * Keys (ver TODAS_CIDADES no JS) dos municípios já atendidos pela MUT.
 * Edite esta lista conforme a cobertura for expandindo.
 */
$mutCidadesAtendidas = [
    'rio-largo',
    'messias',
    'murici',
    'branquinha',
];

$mutCidadesVizinhas = [
    ...$mutCidadesAtendidas,
    'maceio',
    'santa-luzia-do-norte',
    'satuba',
    'coqueiro-seco',
    'marechal-deodoro',
    'pilar',
    'atalaia',
    'capela',
    'cajueiro',
    'vicosa',
    'cha-preta',
    'santana-do-mundau',
    'uniao-dos-palmares',
    'sao-jose-da-laje',
    'ibateguara',
    'joaquim-gomes',
    'flexeiras',
    'sao-luiz-do-quintunde',
    'barra-de-santo-antonio',
    'paripueira',
];

/**
 * Posição manual do pin/rótulo para cidades pequenas onde o centroide
 * geométrico do path cairia num ponto ruim para o texto. Cidades atendidas
 * que não estiverem aqui usam o centroide calculado automaticamente.
 */
$mutPinPosicoes = [
    'branquinha' => ['x' => 913.0, 'y' => 172.5],
    'messias'    => ['x' => 1020.0, 'y' => 222.0],
    'murici'     => ['x' => 973.5, 'y' => 198.5],
    'rio-largo'  => ['x' => 997.0, 'y' => 279.5],
];

/** Mensagem padrão do WhatsApp ao clicar num município atendido; {cidade} é substituído no JS. */
$mutMapaWhatsappTemplate = 'Olá! Gostaria de contratar um novo plano de internet em *{cidade}*. Podem me ajudar?';
$mutMapaWhatsappNumero = MUT_PHONE_ZAP;
