    .mut-map-cobertura path {
        cursor: pointer;
        transition: transform 0.3s ease, fill 0.3s ease, filter 0.3s ease;
        stroke: var(--surface, #fff);
        stroke-width: 3;
        stroke-linejoin: round;
        transform-origin: center;
