    .mut-map-cobertura path.indisponivel {
        fill: #9db9cf !important;
        opacity: 0.6;
        cursor: not-allowed;
    }

    .mut-map-cobertura path.indisponivel:hover {
        fill: #ff9090 !important;
        filter: drop-shadow(0 4px 12px rgba(195, 9, 8, 0.4));
        transform: scale(1.01);
    }

    .mut-map-cobertura path.vizinha {
        fill: #7997ad !important;
    }

    .mut-map-cobertura path.disponivel {
        fill: var(--primary, #0a449a);
    }

    .mut-map-cobertura path.disponivel:hover {
        fill: var(--accent, #c30908);
        filter: drop-shadow(0 4px 12px rgba(8, 42, 195, 0.4));
        transform: scale(1.01);
    }

    .mut-map-cobertura__legend {
        display: flex;
        width: 100%;
        justify-content: center;
        grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
        gap: 3rem;
        margin-top: 20px;
    }

    .mut-map-cobertura__legend-item { display: flex; align-items: center; gap: 10px; font-size: 0.9rem; color: var(--muted, #555); }

    .mut-map-cobertura__legend-color { width: 20px; height: 20px; border-radius: 4px; border: 2px solid var(--border, #999); display: inline-block; }
    .mut-map-cobertura__legend-color--ativo { background: var(--primary, #0a449a); }
    .mut-map-cobertura__legend-color--inativo { background: #9db9cf; }

    .mut-map-cobertura__tooltip {
        position: fixed;
        background: #1a1a1a;
        color: #fff;
        padding: 12px 16px;
        border-radius: 8px;
        font-size: 14px;
        font-weight: 600;
        pointer-events: none;
        z-index: 1000;
        display: none;
        white-space: nowrap;
