            { key: 'vicosa', nome: 'Viçosa', path: 'M862.156 169.054L861.589 209.134L862.609 223.767L862.867 230.209L860.425 237.283L853.276 258.084L849.377 269.431L826.312 263.474L824.921 262.956L811.35 258.181L810.169 259.864L807.678 259.022L805.317 260.852L803.165 260.674L802.049 264.639L799.752 265.255L791.212 267.505L792.069 269.188L795.693 274.271L774.794 257.857L775.733 254.717L781.038 236.943L781.248 236.749L784.322 240.553L786.182 240.067L784.402 238.06L784.532 231.083L795.498 199.793L798.669 198.353L801.063 198.919L802.89 200.927L801.354 203.662L805.301 204.18L806.53 206.43L811.771 206.285L811.431 209.02L813.469 210.218L821.508 207.499L829.434 204.828L839.139 201.04L862.156 169.054Z' },

        ];

    const PIN_POSICOES = <?= json_encode($mutPinPosicoes, JSON_UNESCAPED_UNICODE) ?>;
    const CIDADES_ATENDIDAS = <?= json_encode(array_values($mutCidadesAtendidas), JSON_UNESCAPED_UNICODE) ?>;
    const CIDADES_VIZINHAS = <?= json_encode(array_values($mutCidadesVizinhas), JSON_UNESCAPED_UNICODE) ?>;
    const WHATSAPP_TEMPLATE = <?= json_encode($mutMapaWhatsappTemplate, JSON_UNESCAPED_UNICODE) ?>;
    const WHATSAPP_NUMERO = <?= json_encode($mutMapaWhatsappNumero) ?>;
    const DESTACA_CIDADE_VIZINHA = <?= json_encode($destacaVizinha) ?>;

    const mapCidades = new Map(TODAS_CIDADES.map(function (c) { return [c.key, c]; }));

    function calcularCentroide(pathData) {
        const numeros = pathData.match(/[\d.]+/g);
        if (!numeros || numeros.length < 2) return { x: 0, y: 0 };

        let sumX = 0, sumY = 0;
        for (let i = 0; i < numeros.length - 1; i += 2) {
            sumX += parseFloat(numeros[i]);
            sumY += parseFloat(numeros[i + 1]);
        }

        const count = Math.floor(numeros.length / 2);
        return { x: sumX / count, y: sumY / count };
    }

    // Percorre um path SVG (comandos M/L/H/V, absolutos e relativos) e retorna
    // todos os pontos (x,y) absolutos visitados. Precisa entender H/V como eixo
    // único — um regex ingênuo que agrupa "todo número de 2 em 2" desalinha os
    // pares sempre que um desses comandos aparece, distorcendo o bounding box.
    function pontosDoPath(pathData) {
        const tokens = pathData.match(/[MLHVZmlhvz]|-?\d*\.?\d+(?:e-?\d+)?/g) || [];
        const pontos = [];
        let curX = 0, curY = 0, cmd = null, i = 0;

        while (i < tokens.length) {
            const t = tokens[i];
            if (/^[MLHVZmlhvz]$/.test(t)) {
                cmd = t;
                i += 1;
                continue;
            }

            switch (cmd) {
                case 'M': case 'L':
                    curX = parseFloat(tokens[i]); curY = parseFloat(tokens[i + 1]); i += 2;
                    break;
                case 'm': case 'l':
                    curX += parseFloat(tokens[i]); curY += parseFloat(tokens[i + 1]); i += 2;
                    break;
                case 'H':
                    curX = parseFloat(tokens[i]); i += 1;
                    break;
                case 'h':
                    curX += parseFloat(tokens[i]); i += 1;
                    break;
                case 'V':
                    curY = parseFloat(tokens[i]); i += 1;
                    break;
                case 'v':
                    curY += parseFloat(tokens[i]); i += 1;
                    break;
                default:
                    i += 1;
                    continue;
            }
            pontos.push({ x: curX, y: curY });
        }

        return pontos;
    }

    function calcularBoundingBox(cidades) {
        let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;

        cidades.forEach(function (cidade) {
            pontosDoPath(cidade.path).forEach(function (p) {
                if (p.x < minX) minX = p.x;
                if (p.x > maxX) maxX = p.x;
                if (p.y < minY) minY = p.y;
                if (p.y > maxY) maxY = p.y;
            });
        });

        return { minX: minX, minY: minY, maxX: maxX, maxY: maxY };
    }

    function montarSVG() {
        const cidadesParaDesenhar = DESTACA_CIDADE_VIZINHA
            ? TODAS_CIDADES.filter(function (cidade) { return CIDADES_VIZINHAS.indexOf(cidade.key) !== -1; })
            : TODAS_CIDADES;

        let viewBox = '0 0 1294 710';
        if (DESTACA_CIDADE_VIZINHA) {
            // O enquadramento parte só das cidades ATENDIDAS (não das vizinhas
            // inteiras, que puxariam o zoom pra fora incluindo Maceió etc.).
            // Padding proporcional ao maior lado do bounding box, então o
            // enquadramento se ajusta sozinho se a lista de atendidas mudar.
            const cidadesAtendidasObj = TODAS_CIDADES.filter(function (cidade) {
                return CIDADES_ATENDIDAS.indexOf(cidade.key) !== -1;
            });
            const box = calcularBoundingBox(cidadesAtendidasObj);
            const largura = box.maxX - box.minX;
            const altura = box.maxY - box.minY;
            const padding = Math.max(largura, altura) * 0.7;
            viewBox = [
                box.minX - padding,
                box.minY - padding,
                largura + padding * 2,
                altura + padding * 2,
            ].join(' ');
        }

        let svgContent = '<svg viewBox="' + viewBox + '" fill="none" xmlns="http://www.w3.org/2000/svg">' +
            '<defs><symbol id="mut-mapa-pin-icon" viewBox="0 0 36 46">' +
            '<path d="M18 3.14899L19.6102 3.22926L21.2063 3.46389L22.7602 3.85906L24.2438 4.40242L25.6641 5.08779L26.9789 5.90899L28.1813 6.85369L29.257 7.90953L30.1922 9.06416L30.9727 10.3052L31.5914 11.6204L32.0414 12.9788L32.3156 14.3742L32.4 15.7882L32.3156 18.1839L32.0555 20.5611L31.6266 22.9197L31.0359 25.2599L30.2695 27.5506L29.3484 29.7981L28.2586 31.9962L27.0211 34.1203L25.6289 36.1764L24.1031 38.1522L22.4227 40.0354L20.6227 41.826L20.0602 42.2521L19.4273 42.5608L18.7313 42.746L18 42.8325L17.2688 42.746L16.5727 42.5608L15.9398 42.2521L15.3773 41.826L13.5773 40.0354L11.8969 38.1522L10.3711 36.1764L8.97891 34.1203L7.74141 31.9962L6.65156 29.7981L5.73047 27.5506L4.96406 25.2599L4.37344 22.9197L3.94453 20.5611L3.68438 18.1839L3.6 15.7882L3.69141 14.3742L3.95859 12.9788L4.40156 11.6204L5.02031 10.3052L5.80781 9.06416L6.74297 7.90953L7.81875 6.85369L9.02109 5.90899L10.3359 5.08779L11.7492 4.40242L13.2469 3.85906L14.7938 3.46389L16.3828 3.22926L18 3.14899Z" fill="white"/>' +
            '<path fill-rule="evenodd" clip-rule="evenodd" d="M18 3.14899L19.6102 3.22926L21.2063 3.46389L22.7602 3.85906L24.2438 4.40242L25.6641 5.08779L26.9789 5.90899L28.1813 6.85369L29.257 7.90953L30.1922 9.06416L30.9727 10.3052L31.5914 11.6204L32.0414 12.9788L32.3156 14.3742L32.4 15.7882L32.3156 18.1839L32.0555 20.5611L31.6266 22.9197L31.0359 25.2599L30.2695 27.5506L29.3484 29.7981L28.2586 31.9962L27.0211 34.1203L25.6289 36.1764L24.1031 38.1522L22.4227 40.0354L20.6227 41.826L20.0602 42.2521L19.4273 42.5608L18.7313 42.746L18 42.8325L17.2688 42.746L16.5727 42.5608L15.9398 42.2521L15.3773 41.826L13.5773 40.0354L11.8969 38.1522L10.3711 36.1764L8.97891 34.1203L7.74141 31.9962L6.65156 29.7981L5.73047 27.5506L4.96406 25.2599L4.37344 22.9197L3.94453 20.5611L3.68438 18.1839L3.6 15.7882L3.69141 14.3742L3.95859 12.9788L4.40156 11.6204L5.02031 10.3052L5.80781 9.06416L6.74297 7.90953L7.81875 6.85369L9.02109 5.90899L10.3359 5.08779L11.7492 4.40242L13.2469 3.85906L14.7938 3.46389L16.3828 3.22926L18 3.14899ZM16.5586 9.58899L17.7047 9.4655L18.8648 9.50872L20.0039 9.71866L21.0867 10.0768L22.0922 10.5831L22.9922 11.2376L23.7586 11.997L24.3773 12.8553L24.8273 13.7938L25.1086 14.7817L25.2 15.7944V15.8005L25.1086 16.8193L24.8273 17.8072L24.3773 18.7396L23.7586 19.604L22.9922 20.3635L22.0922 21.0056L21.0867 21.5119L20.0039 21.8762L18.8648 22.0862L17.7047 22.1047L16.5586 21.9812L15.4477 21.6972L14.4 21.2588L13.4438 20.6784L12.6141 19.9807L11.918 19.1656L11.3766 18.2642L11.0039 17.3009L10.8211 16.3007V15.2757L11.0039 14.2754L11.3766 13.3122L11.918 12.4046L12.6141 11.5895L13.4438 10.8856L14.4 10.3052L15.4477 9.87919L16.5586 9.58899Z" fill="#FF0000"/>' +
            '<path d="M18 12.6268L18.7945 12.7133L19.5609 12.9479L20.243 13.3246L20.8195 13.8247L21.2484 14.4174L21.5086 15.0905L21.6 15.7944L21.5086 16.4921L21.2484 17.1651L20.8195 17.764L20.243 18.2703L19.5609 18.647L18.7945 18.8816L18 18.9619L17.1984 18.8816L16.432 18.647L15.757 18.2703L15.1875 17.764L14.7586 17.1651L14.4914 16.4921L14.4 15.7944L14.4914 15.0905L14.7586 14.4174L15.1875 13.8247L15.757 13.3246L16.432 12.9479L17.1984 12.7133L18 12.6268Z" fill="white"/>' +
            '</symbol></defs>';

        cidadesParaDesenhar.forEach(function (cidade) {
            svgContent += '<path id="mut-mapa-' + cidade.key + '" data-key="' + cidade.key + '" d="' + cidade.path + '" stroke="white" stroke-width="3" stroke-linejoin="round" />';
        });

        TODAS_CIDADES.forEach(function (cidade) {
            if (CIDADES_ATENDIDAS.indexOf(cidade.key) === -1) return;

            const centroide = PIN_POSICOES[cidade.key] || calcularCentroide(cidade.path);

            svgContent += '<g class="mut-map-cobertura__marker" style="pointer-events: none;">' +
                '<use href="#mut-mapa-pin-icon" x="' + (centroide.x - 6) + '" y="' + (centroide.y - 15) + '" width="12" height="15.33" />' +
                '<text x="' + centroide.x + '" y="' + (centroide.y + 12) + '" text-anchor="middle" font-size="12" font-weight="bold" fill="white" style="pointer-events: none;">' + cidade.nome + '</text>' +
                '</g>';
        });

        svgContent += '</svg>';

        document.getElementById('mutMapaContainer').innerHTML = svgContent;
    }

    function inicializarInteratividade() {
        const paths = document.querySelectorAll('.mut-map-cobertura path[data-key]');
        const tooltip = document.getElementById('mutMapaTooltip');

        paths.forEach(function (path) {
            const cidadeId = path.getAttribute('data-key');
            const cidade = mapCidades.get(cidadeId);
            if (!cidade) return;

            const temCobertura = CIDADES_ATENDIDAS.indexOf(cidadeId) !== -1;
            path.classList.add(temCobertura ? 'disponivel' : 'indisponivel');

            path.addEventListener('mouseenter', function () {
                tooltip.textContent = (temCobertura ? '✓ ' : '⏳ ') + cidade.nome;
                tooltip.classList.add('active');
                if (!temCobertura) tooltip.classList.add('sem-cobertura');
            });

            path.addEventListener('mousemove', function (e) {
                tooltip.style.left = (e.clientX + 12) + 'px';
                tooltip.style.top = (e.clientY + 12) + 'px';
            });

            path.addEventListener('mouseleave', function () {
                tooltip.classList.remove('active', 'sem-cobertura');
            });

            if (temCobertura) {
                path.addEventListener('click', function () {
                    const texto = WHATSAPP_TEMPLATE.replace('{cidade}', cidade.nome);
                    const url = 'https://wa.me/' + WHATSAPP_NUMERO + '?text=' + encodeURIComponent(texto);
                    window.open(url, '_blank', 'noopener');
                });
            }
        });
    }

    function iniciar() {
        montarSVG();
        inicializarInteratividade();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', iniciar);
    } else {
        iniciar();
    }
})();
</script>
